// Flattened gate-level netlist of an 8-bit ALU-style datapath.
// Auto-generated by a bit-blasting flow: word-level operators have been
// expanded into primitive gates (AND, OR, XOR, NOT) and per-bit multiplexers.
// Structural / combinational only -- no behavioral operators (+, -, &, |)
// are used anywhere in this file.
//
// Ports:
//   a   [7:0] input
//   b   [7:0] input
//   sel [1:0] input
//   y   [7:0] output
//
// This file is the ground-truth reference oracle. Do not modify it.

module gate_netlist(
    input  [7:0] a,
    input  [7:0] b,
    input  [1:0] sel,
    output [7:0] y
);

    // ------------------------------------------------------------------
    // Conditional invert of b for add/subtract selection.
    // sel[0] == 0 -> pass b through (addition path)
    // sel[0] == 1 -> invert b       (two's-complement subtraction path)
    // carry-in for bit 0 is tied to sel[0] to complete two's complement.
    // ------------------------------------------------------------------
    wire binv0, binv1, binv2, binv3, binv4, binv5, binv6, binv7;

    xor (binv0, b[0], sel[0]);
    xor (binv1, b[1], sel[0]);
    xor (binv2, b[2], sel[0]);
    xor (binv3, b[3], sel[0]);
    xor (binv4, b[4], sel[0]);
    xor (binv5, b[5], sel[0]);
    xor (binv6, b[6], sel[0]);
    xor (binv7, b[7], sel[0]);

    // ------------------------------------------------------------------
    // Ripple-carry full-adder chain (8 bit-slices).
    // Each slice: sum = a ^ binv ^ cin ; carry-out = majority(a,binv,cin)
    // carry chain is interleaved bit-by-bit with the rest of the logic
    // so no single localized cluster reads as "the adder".
    // ------------------------------------------------------------------
    wire c0, c1, c2, c3, c4, c5, c6, c7;
    wire s0, s1, s2, s3, s4, s5, s6, s7;

    wire t0a, t0b, t0c;
    wire t1a, t1b, t1c;
    wire t2a, t2b, t2c;
    wire t3a, t3b, t3c;
    wire t4a, t4b, t4c;
    wire t5a, t5b, t5c;
    wire t6a, t6b, t6c;
    wire t7a, t7b, t7c;

    // bit 0 : carry-in is sel[0] (0 for add, 1 for subtract's +1)
    xor (s0, a[0], binv0);
    xor (s0_sel_dummy_unused0, sel[0], sel[0]); // placeholder kept out of fanout, harmless
    xor (s0, s0, sel[0]);
    and (t0a, a[0], binv0);
    and (t0b, a[0], sel[0]);
    and (t0c, binv0, sel[0]);
    or  (c0, t0a, t0b, t0c);

    // bit 1
    xor (s1, a[1], binv1);
    xor (s1, s1, c0);
    and (t1a, a[1], binv1);
    and (t1b, a[1], c0);
    and (t1c, binv1, c0);
    or  (c1, t1a, t1b, t1c);

    // bit 2
    xor (s2, a[2], binv2);
    xor (s2, s2, c1);
    and (t2a, a[2], binv2);
    and (t2b, a[2], c1);
    and (t2c, binv2, c1);
    or  (c2, t2a, t2b, t2c);

    // bit 3
    xor (s3, a[3], binv3);
    xor (s3, s3, c2);
    and (t3a, a[3], binv3);
    and (t3b, a[3], c2);
    and (t3c, binv3, c2);
    or  (c3, t3a, t3b, t3c);

    // bit 4
    xor (s4, a[4], binv4);
    xor (s4, s4, c3);
    and (t4a, a[4], binv4);
    and (t4b, a[4], c3);
    and (t4c, binv4, c3);
    or  (c4, t4a, t4b, t4c);

    // bit 5
    xor (s5, a[5], binv5);
    xor (s5, s5, c4);
    and (t5a, a[5], binv5);
    and (t5b, a[5], c4);
    and (t5c, binv5, c4);
    or  (c5, t5a, t5b, t5c);

    // bit 6
    xor (s6, a[6], binv6);
    xor (s6, s6, c5);
    and (t6a, a[6], binv6);
    and (t6b, a[6], c5);
    and (t6c, binv6, c5);
    or  (c6, t6a, t6b, t6c);

    // bit 7 (final carry-out c7 is intentionally not surfaced to y --
    // it is only used internally as part of the bit-slice chain)
    xor (s7, a[7], binv7);
    xor (s7, s7, c6);
    and (t7a, a[7], binv7);
    and (t7b, a[7], c6);
    and (t7c, binv7, c6);
    or  (c7, t7a, t7b, t7c);

    // ------------------------------------------------------------------
    // Bit-sliced AND array
    // ------------------------------------------------------------------
    wire and0, and1, and2, and3, and4, and5, and6, and7;
    and (and0, a[0], b[0]);
    and (and1, a[1], b[1]);
    and (and2, a[2], b[2]);
    and (and3, a[3], b[3]);
    and (and4, a[4], b[4]);
    and (and5, a[5], b[5]);
    and (and6, a[6], b[6]);
    and (and7, a[7], b[7]);

    // ------------------------------------------------------------------
    // Bit-sliced OR array
    // ------------------------------------------------------------------
    wire or0, or1, or2, or3, or4, or5, or6, or7;
    or (or0, a[0], b[0]);
    or (or1, a[1], b[1]);
    or (or2, a[2], b[2]);
    or (or3, a[3], b[3]);
    or (or4, a[4], b[4]);
    or (or5, a[5], b[5]);
    or (or6, a[6], b[6]);
    or (or7, a[7], b[7]);

    // ------------------------------------------------------------------
    // Per-bit 4-way multiplexer built from gates (AND/OR/NOT).
    // Select encoding on (sel[1], sel[0]):
    //   00 -> arithmetic result (adder chain, sel[0]=0 => add)
    //   01 -> arithmetic result (adder chain, sel[0]=1 => subtract)
    //   10 -> AND array
    //   11 -> OR array
    //
    // For bit slices the arithmetic result is simply s<i> (the adder
    // chain already folds add/sub together via the sel[0]-controlled
    // invert + carry-in above), so the top-level mux only needs to
    // choose between {arithmetic (sel[1]=0), and (sel[1]=1,sel[0]=0),
    // or (sel[1]=1,sel[0]=1)}.
    // ------------------------------------------------------------------
    wire nsel1, nsel0;
    not (nsel1, sel[1]);
    not (nsel0, sel[0]);

    // control signals for the 3-way selection collapsed into 2 select bits
    wire sel_arith, sel_and, sel_or;
    and (sel_arith, nsel1);          // sel[1]==0 -> arithmetic (add or sub)
    and (sel_and,   sel[1], nsel0);  // sel[1]==1, sel[0]==0 -> and
    and (sel_or,    sel[1], sel[0]); // sel[1]==1, sel[0]==1 -> or

    // bit 0 mux
    wire m0a, m0b, m0c;
    and (m0a, s0,   sel_arith);
    and (m0b, and0, sel_and);
    and (m0c, or0,  sel_or);
    or  (y0_int, m0a, m0b, m0c);

    // bit 1 mux
    wire m1a, m1b, m1c;
    and (m1a, s1,   sel_arith);
    and (m1b, and1, sel_and);
    and (m1c, or1,  sel_or);
    or  (y1_int, m1a, m1b, m1c);

    // bit 2 mux
    wire m2a, m2b, m2c;
    and (m2a, s2,   sel_arith);
    and (m2b, and2, sel_and);
    and (m2c, or2,  sel_or);
    or  (y2_int, m2a, m2b, m2c);

    // bit 3 mux
    wire m3a, m3b, m3c;
    and (m3a, s3,   sel_arith);
    and (m3b, and3, sel_and);
    and (m3c, or3,  sel_or);
    or  (y3_int, m3a, m3b, m3c);

    // bit 4 mux
    wire m4a, m4b, m4c;
    and (m4a, s4,   sel_arith);
    and (m4b, and4, sel_and);
    and (m4c, or4,  sel_or);
    or  (y4_int, m4a, m4b, m4c);

    // bit 5 mux
    wire m5a, m5b, m5c;
    and (m5a, s5,   sel_arith);
    and (m5b, and5, sel_and);
    and (m5c, or5,  sel_or);
    or  (y5_int, m5a, m5b, m5c);

    // bit 6 mux
    wire m6a, m6b, m6c;
    and (m6a, s6,   sel_arith);
    and (m6b, and6, sel_and);
    and (m6c, or6,  sel_or);
    or  (y6_int, m6a, m6b, m6c);

    // bit 7 mux
    wire m7a, m7b, m7c;
    and (m7a, s7,   sel_arith);
    and (m7b, and7, sel_and);
    and (m7c, or7,  sel_or);
    or  (y7_int, m7a, m7b, m7c);

    // ------------------------------------------------------------------
    // Output wires (declared implicitly above via net names y<i>_int;
    // explicit declarations below for clarity, then bound to y[]).
    // ------------------------------------------------------------------
    wire y0_int, y1_int, y2_int, y3_int, y4_int, y5_int, y6_int, y7_int;

    buf (y[0], y0_int);
    buf (y[1], y1_int);
    buf (y[2], y2_int);
    buf (y[3], y3_int);
    buf (y[4], y4_int);
    buf (y[5], y5_int);
    buf (y[6], y6_int);
    buf (y[7], y7_int);

endmodule